    ok(pg.locator('#lvList li').count()==4 and pg.evaluate("[...document.querySelectorAll('#lvList .lvdist')].every(e=>/\\d+(\\.\\d+)? (m|km) (N|NE|E|SE|S|SW|W|NW)$/.test(e.textContent.trim()))") and 'Martian Base' in pg.inner_text('#lvFrom'),'Live views lists 4 nearest panoramas with distance and direction from base')
    ok(pg.evaluate("[...document.querySelectorAll('#lvList img')].every(i=>i.getAttribute('src').startsWith('assets/thumbs/'))"),'Live views show panorama thumbnails')
    ok(pg.locator('[data-slot=capcom] img').count()==1 and pg.locator('[data-slot=empty] img').count()==1,'CAPCOM avatar and the pixel-rover GIF fill their slots')
